//#region src/shared/services/utils/logger.ts
var e = (e, t) => `[${e}]: ${t}`, t = {
	log: (t, n, ...r) => {
		console.log(e(t, n), ...r);
	},
	warn: (t, n, ...r) => {
		console.warn(e(t, n), ...r);
	},
	error: (t, n, ...r) => {
		console.error(e(t, n), ...r);
	},
	debug: (t, n, ...r) => {
		console.debug(e(t, n), ...r);
	}
};
//#endregion
export { t };
